INSERT INTO picture360_images (examId, specialty, conditionName, imageUrl, keyFeatures, examPearl, optionA, optionB, optionC, optionD, correctAnswer, explanation, status) VALUES
(1, 'ECG', 'Sinus Bradycardia', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ecg_sinus-bradycardia-placeholder.webp', 'Regular rhythm with rate below 60 bpm; normal P wave morphology preceding each QRS; normal PR interval; normal QRS duration; each P wave followed by a QRS complex', 'Sinus bradycardia is common in athletes and during sleep. Pathological causes include hypothyroidism, raised intracranial pressure (Cushing reflex), hypothermia, and drugs (beta-blockers, calcium channel blockers, digoxin). Treatment is only needed if symptomatic — atropine for acute symptomatic bradycardia, permanent pacemaker for chronic symptomatic bradycardia', 'Normal sinus rhythm at a rate below 60 bpm', 'First degree heart block', 'Junctional rhythm', 'Atrial fibrillation with slow ventricular response', 'A', 'Sinus bradycardia is a regular rhythm with a rate below 60 bpm with normal P waves preceding each QRS complex. It is physiological in athletes and during sleep. Pathological causes include hypothyroidism, raised ICP, hypothermia, inferior MI, and drugs (beta-blockers, digoxin, calcium channel blockers). Treatment is only required if symptomatic. Acute management is IV atropine 500mcg. Chronic symptomatic bradycardia may require a permanent pacemaker.', 'active'),
(1, 'ECG', 'Sinus Tachycardia', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ecg_sinus-tachycardia-placeholder.webp', 'Regular rhythm with rate above 100 bpm; normal P wave morphology preceding each QRS; normal PR interval; normal QRS duration; P waves may be difficult to identify at very fast rates as they merge with preceding T waves', 'Sinus tachycardia is a physiological response — always look for the underlying cause rather than treating the heart rate directly. Common causes: pain, anxiety, fever, anaemia, hypovolaemia, heart failure, thyrotoxicosis, PE, sepsis. The maximum predicted heart rate is 220 minus age', 'Physiological tachycardia — identify and treat the underlying cause', 'Supraventricular tachycardia', 'Atrial flutter with 2:1 block', 'Ventricular tachycardia', 'A', 'Sinus tachycardia is a regular rhythm above 100 bpm with normal P waves before each QRS. It is a physiological response to an underlying stimulus and should not be treated by simply lowering the heart rate. Common causes include pain, fever, anaemia, hypovolaemia, sepsis, thyrotoxicosis, heart failure, and pulmonary embolism. Management is directed at identifying and treating the underlying cause. At rates above 150 bpm, consider alternative diagnoses such as SVT or atrial flutter.', 'active'),
(1, 'ECG', 'Pericarditis', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ecg_pericarditis-placeholder.webp', 'Widespread saddle-shaped (concave upward) ST elevation in multiple territories not conforming to a single coronary artery distribution; PR depression (especially in lead II); reciprocal ST depression and PR elevation in aVR; no pathological Q waves', 'The key distinguishing feature from STEMI is that pericarditis causes widespread concave ST elevation across multiple territories, whereas STEMI causes convex ST elevation in a single coronary territory with reciprocal changes. PR depression is relatively specific for pericarditis. Troponin may be mildly elevated (myopericarditis)', 'Widespread concave ST elevation from pericardial inflammation', 'Acute anterior STEMI', 'Benign early repolarisation', 'Takotsubo cardiomyopathy', 'A', 'Pericarditis produces characteristic ECG changes: widespread saddle-shaped (concave upward) ST elevation across multiple territories, PR depression (especially lead II), and reciprocal ST depression with PR elevation in aVR. Unlike STEMI, the ST elevation does not conform to a single coronary artery territory and there are no reciprocal ST changes in other leads. ECG changes evolve through four stages. Treatment is NSAIDs plus colchicine. Troponin may be mildly elevated indicating myopericarditis.', 'active'),
(1, 'ECG', 'Pulmonary Embolism S1Q3T3 pattern', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ecg_pe-s1q3t3-placeholder.webp', 'S1Q3T3 pattern: deep S wave in lead I, pathological Q wave in lead III, inverted T wave in lead III; sinus tachycardia (most common ECG finding in PE); right axis deviation; right bundle branch block pattern; T wave inversion in anterior leads V1-V4 (right ventricular strain)', 'The most common ECG finding in PE is sinus tachycardia, not S1Q3T3. The classic S1Q3T3 pattern is present in only 10-20% of PE cases. Right heart strain signs (T wave inversion V1-V4, RBBB, right axis deviation) indicate massive PE. A normal ECG does not exclude PE. CTPA is the gold standard investigation', 'Right heart strain pattern suggesting acute pulmonary embolism', 'Acute inferior STEMI', 'Right ventricular hypertrophy', 'Pericarditis', 'A', 'The S1Q3T3 pattern (deep S wave in lead I, Q wave and inverted T wave in lead III) is a classic but insensitive sign of acute pulmonary embolism, present in only 10-20% of cases. The most common ECG finding in PE is sinus tachycardia. Other signs of right heart strain include T wave inversion in V1-V4, right axis deviation, and RBBB. A normal ECG does not exclude PE. CTPA is the definitive investigation. Treatment is anticoagulation; thrombolysis for massive PE with haemodynamic compromise.', 'active'),
(1, 'ECG', 'Brugada Syndrome', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ecg_brugada-placeholder.webp', 'Coved ST elevation greater than 2mm in V1-V3 followed by a negative T wave (Type 1 Brugada pattern); may have RBBB morphology; normal QT interval; structurally normal heart; associated with sudden cardiac death', 'Brugada syndrome is an inherited channelopathy (sodium channel dysfunction) causing ventricular arrhythmias and sudden cardiac death. Type 1 pattern (coved) is diagnostic; Type 2 (saddle-back) requires provocation testing with ajmaline or flecainide. Treatment is an implantable cardioverter-defibrillator (ICD). Avoid fever, excessive alcohol, and certain drugs', 'Inherited channelopathy with characteristic coved ST elevation in V1-V3', 'Acute anterior STEMI', 'Right bundle branch block', 'Pericarditis', 'A', 'Brugada syndrome is an inherited sodium channelopathy associated with ventricular arrhythmias and sudden cardiac death, typically in young males. The Type 1 (coved) pattern shows ST elevation greater than 2mm in V1-V3 with a negative T wave. The heart is structurally normal. Diagnosis requires the Type 1 pattern plus clinical criteria (syncope, documented VF, family history of sudden death). Treatment is an ICD for high-risk patients. Fever should be treated aggressively as it can unmask the pattern.', 'active'),
(1, 'ECG', 'Left Ventricular Hypertrophy', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ecg_lvh-placeholder.webp', 'Increased QRS voltage: S wave in V1 plus R wave in V5 or V6 greater than 35mm (Sokolow-Lyon criteria); left axis deviation; ST depression and T wave inversion in lateral leads (strain pattern); may have broad notched P waves (P mitrale)', 'LVH voltage criteria alone have low sensitivity. The strain pattern (ST depression and T wave inversion in lateral leads) increases specificity and indicates more severe hypertrophy. Common causes: hypertension (most common), aortic stenosis, hypertrophic cardiomyopathy, aortic regurgitation, coarctation of the aorta', 'Increased ventricular mass most commonly from hypertension', 'Right ventricular hypertrophy', 'Left bundle branch block', 'Anterior STEMI', 'A', 'Left ventricular hypertrophy on ECG is diagnosed using voltage criteria such as Sokolow-Lyon (S in V1 + R in V5/V6 > 35mm) or Cornell criteria. A lateral strain pattern (ST depression and T wave inversion in I, aVL, V5-V6) indicates more severe hypertrophy and carries prognostic significance. Common causes include hypertension, aortic stenosis, hypertrophic cardiomyopathy, and aortic regurgitation. Echocardiography is needed to confirm structural LVH and assess for underlying cause.', 'active'),
(1, 'ECG', 'Right Ventricular Hypertrophy', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ecg_rvh-placeholder.webp', 'Right axis deviation; dominant R wave in V1 (R greater than S); right ventricular strain pattern with ST depression and T wave inversion in right precordial leads V1-V3 and inferior leads; may have P pulmonale (peaked P waves in lead II suggesting right atrial enlargement)', 'RVH causes a dominant R wave in V1 because the right ventricle becomes the dominant electrical force. Common causes: pulmonary hypertension, pulmonary stenosis, chronic lung disease (cor pulmonale), Eisenmenger syndrome, and large ASD or VSD. P pulmonale (peaked P waves greater than 2.5mm in lead II) suggests associated right atrial enlargement', 'Right ventricular enlargement most commonly from pulmonary hypertension', 'Left ventricular hypertrophy', 'Right bundle branch block', 'Posterior STEMI', 'A', 'Right ventricular hypertrophy on ECG shows right axis deviation, dominant R wave in V1 (R > S), and a right ventricular strain pattern (ST depression and T wave inversion in V1-V3). P pulmonale (peaked P waves > 2.5mm in lead II) suggests associated right atrial enlargement. Common causes include pulmonary hypertension, pulmonary stenosis, chronic lung disease (cor pulmonale), and congenital heart disease. Echocardiography is required to confirm the diagnosis and assess the underlying cause.', 'active'),
(1, 'ECG', 'Hypothermia Osborn J waves', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ecg_hypothermia-placeholder.webp', 'Osborn J waves: positive deflection at the J point (junction of QRS and ST segment); bradycardia; prolonged PR interval; prolonged QT interval; muscle tremor artefact from shivering; atrial fibrillation may occur below 32 degrees Celsius', 'Osborn (J) waves are pathognomonic of hypothermia. Their size correlates with the degree of hypothermia. Below 30 degrees Celsius, the risk of ventricular fibrillation increases significantly. Rewarming should be gradual. Defibrillation may be ineffective below 30 degrees — focus on rewarming. Remember: the patient is not dead until they are warm and dead', 'Hypothermia with pathognomonic J waves at the QRS-ST junction', 'Hyperkalaemia with peaked T waves', 'Brugada syndrome', 'Early repolarisation', 'A', 'Osborn (J) waves are positive deflections at the J point, pathognomonic of hypothermia. Their amplitude correlates with the degree of hypothermia. Other ECG features include bradycardia, prolonged PR and QT intervals, and shivering artefact. Below 32 degrees Celsius, atrial fibrillation commonly occurs. Below 30 degrees, the risk of ventricular fibrillation increases significantly and defibrillation may be ineffective until the patient is rewarmed. The principle is: the patient is not dead until they are warm and dead.', 'active'),
(1, 'ECG', 'Hypercalcaemia', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ecg_hypercalcaemia-placeholder.webp', 'Shortened QT interval (the hallmark ECG finding); shortened ST segment; broad T waves; PR prolongation in severe cases; Osborn J waves may appear in severe hypercalcaemia; bradycardia and heart block in extreme cases', 'Hypercalcaemia shortens the QT interval (opposite to hypocalcaemia which prolongs it). Common causes: primary hyperparathyroidism (most common outpatient cause) and malignancy (most common inpatient cause). Severe hypercalcaemia (above 3.5 mmol/L) is a medical emergency requiring IV normal saline rehydration', 'Shortened QT interval from elevated serum calcium', 'Hypokalaemia with U waves', 'Digoxin effect', 'Hypothermia', 'A', 'Hypercalcaemia characteristically shortens the QT interval on ECG by shortening the ST segment. This is the opposite of hypocalcaemia, which prolongs the QT interval. In severe hypercalcaemia, Osborn J waves, PR prolongation, and bradycardia may occur. The two most common causes are primary hyperparathyroidism (outpatient) and malignancy (inpatient). Severe hypercalcaemia (above 3.5 mmol/L) is a medical emergency treated with aggressive IV saline rehydration followed by IV bisphosphonates.', 'active'),
(1, 'ECG', 'Hypertrophic Cardiomyopathy', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ecg_hcm-placeholder.webp', 'Left ventricular hypertrophy voltage criteria; deep narrow Q waves in lateral and inferior leads (septal hypertrophy); T wave inversion in lateral leads; may have pre-excitation pattern; ST segment abnormalities', 'HCM is the most common cause of sudden cardiac death in young athletes. It is autosomal dominant with variable penetrance. Deep narrow Q waves in the lateral leads reflect septal hypertrophy. ECG is abnormal in 75-95% of HCM patients. All first-degree relatives should be screened with ECG and echocardiography', 'Inherited cardiomyopathy with asymmetric septal hypertrophy', 'Aortic stenosis with secondary LVH', 'Athlete heart with physiological hypertrophy', 'Previous anterior myocardial infarction', 'A', 'Hypertrophic cardiomyopathy (HCM) is an autosomal dominant condition and the most common cause of sudden cardiac death in young athletes. ECG abnormalities are present in 75-95% of cases and include LVH voltage criteria, deep narrow Q waves in lateral and inferior leads (reflecting septal hypertrophy), and T wave inversion. Echocardiography confirms the diagnosis showing asymmetric septal hypertrophy (wall thickness greater than 15mm). All first-degree relatives should be screened. High-risk patients may require an ICD.', 'active');
